package io.scenariomesh.coordinator;import com.fasterxml.jackson.databind.ObjectMapper;import io.scenariomesh.core.Domain.*;import io.scenariomesh.core.Ports.SchedulingStrategy;import io.scenariomesh.protocol.Protocol;import io.scenariomesh.protocol.Protocol.Envelope;import io.scenariomesh.scheduler.FifoSchedulingStrategy;import io.scenariomesh.workerruntime.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;final class WorkerPool implements AutoCloseable{private final ObjectMapper mapper=JsonCodec.create();private final RunRequest request;private final Path dir;private final String token=UUID.randomUUID().toString();private final ServerSocket server;private final Map<String,Process> processes=new HashMap<>();private final List<WorkerConnection> connections=new ArrayList<>();WorkerPool(RunRequest r,Path d)throws Exception{request=r;dir=d;server=new ServerSocket();server.bind(new InetSocketAddress(InetAddress.getLoopbackAddress(),0));server.setSoTimeout(Math.toIntExact(r.config().workerStartupTimeout().toMillis()));try{launch();accept();}catch(Exception e){close();throw e;}}List<ExecutionResult> execute(List<ScenarioTask> tasks)throws InterruptedException{SchedulingStrategy scheduler=new FifoSchedulingStrategy();scheduler.load(tasks);ConcurrentLinkedQueue<ExecutionResult> results=new ConcurrentLinkedQueue<>();ExecutorService exec=Executors.newFixedThreadPool(connections.size());for(WorkerConnection c:connections)exec.submit(()->loop(c,scheduler,results));exec.shutdown();exec.awaitTermination(Long.MAX_VALUE,TimeUnit.NANOSECONDS);return List.copyOf(results);}private void loop(WorkerConnection c,SchedulingStrategy s,ConcurrentLinkedQueue<ExecutionResult> results){for(;;){ScenarioTask task=s.nextEligible(x->true);if(task==null){stop(c);return;}Instant started=Instant.now();try{c.write(Envelope.run(c.workerId,task));Envelope response=c.read();if(response==null){results.add(failure(task,c.workerId,started,"Worker disconnected before returning a result"));return;}if(response.type()==Protocol.Type.RESULT&&response.result()!=null)results.add(response.result());else results.add(failure(task,c.workerId,started,response.error()==null?"Unexpected worker response: "+response.type():response.error()));}catch(Exception e){results.add(failure(task,c.workerId,started,e.getMessage()));return;}}}private ExecutionResult failure(ScenarioTask task,String id,Instant started,String msg){Instant finished=Instant.now();return new ExecutionResult(task.id(),task.displayName(),ResultStatus.WORKER_FAILURE,Duration.between(started,finished),new WorkerId(id),1,started,finished,msg,"WorkerFailure");}private void launch()throws Exception{Files.createDirectories(dir.resolve("logs"));String host=InetAddress.getLoopbackAddress().getHostAddress();int port=server.getLocalPort();for(int i=1;i<=request.config().workerCount();i++){String id="worker-"+i;List<String> args=List.of("--host",host,"--port",Integer.toString(port),"--token",token,"--worker-id",id);List<String> cmd=JavaProcessSupport.command(request.runtimeClasspath(),request.effectiveJvmArgs(),request.effectiveSystemProperties(),WorkerMain.class.getName(),args);Process p=new ProcessBuilder(cmd).directory(request.projectDirectory().toFile()).redirectErrorStream(true).redirectOutput(dir.resolve("logs").resolve(id+".log").toFile()).start();processes.put(id,p);}}private void accept()throws Exception{while(connections.size()<request.config().workerCount()){Socket socket=server.accept();WorkerConnection c=new WorkerConnection(socket);Envelope hello=c.read();if(hello==null||hello.protocolVersion()!=Protocol.VERSION||hello.type()!=Protocol.Type.HELLO||!token.equals(hello.token())||!processes.containsKey(hello.workerId())){c.close();continue;}c.workerId=hello.workerId();connections.add(c);}}private void stop(WorkerConnection c){try{c.write(Envelope.stop(c.workerId));c.read();}catch(Exception ignored){}}public void close(){for(WorkerConnection c:connections)try{c.close();}catch(Exception ignored){}for(Process p:processes.values()){if(!p.isAlive())continue;p.destroy();try{if(!p.waitFor(request.config().workerShutdownTimeout().toMillis(),TimeUnit.MILLISECONDS))p.destroyForcibly();}catch(InterruptedException e){Thread.currentThread().interrupt();p.destroyForcibly();}}try{server.close();}catch(Exception ignored){}}private final class WorkerConnection implements AutoCloseable{final Socket socket;final BufferedReader reader;final BufferedWriter writer;String workerId;WorkerConnection(Socket s)throws Exception{socket=s;reader=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));writer=new BufferedWriter(new OutputStreamWriter(s.getOutputStream(),StandardCharsets.UTF_8));}Envelope read()throws Exception{String line=reader.readLine();return line==null?null:mapper.readValue(line,Envelope.class);}void write(Envelope e)throws Exception{writer.write(mapper.writeValueAsString(e));writer.newLine();writer.flush();}public void close()throws Exception{socket.close();}}}
